let recorder=null,recordStream=null,recordChunks=[],recordTimeout=null,voiceMode=false,voiceRole=null,voiceProcessing=false,currentAudio=null,speechController=null;
function stopVoice(){voiceMode=false;speechController?.abort();if(recorder?.state==='recording')recorder.stop();recordStream?.getTracks().forEach(t=>t.stop());if(currentAudio){currentAudio.pause();URL.revokeObjectURL(currentAudio.src);currentAudio=null}if('speechSynthesis'in window)window.speechSynthesis.cancel()}
let voiceConfig=localRead('voiceConfig',{base:'',key:'',remember:false,sameAsChat:true}),voiceKey=voiceConfig.remember?voiceConfig.key||'':'';
function effectiveVoiceConfig(){return voiceConfig.sameAsChat?{base:config.base,key}:{base:voiceConfig.base,key:voiceKey}}
function voiceReady(){const c=effectiveVoiceConfig();return !!(c.base&&c.key)}
function renderVoiceSettings(embedded=false){
  const html=`<div class="api-section-title"><span>02</span><h3>语音 API</h3><p>录音转文字与文字转语音</p></div><div class="notice">语音服务可以和聊天服务不同。录音会发送至这里配置的语音接口。</div><form id="voiceForm"><label class="check"><input type="checkbox" name="sameAsChat" ${voiceConfig.sameAsChat?'checked':''}>使用已保存的聊天 API 地址和密钥</label><div id="voiceCredentials" ${voiceConfig.sameAsChat?'hidden':''}><label>语音接口地址 · Base URL<input name="voiceBase" type="url" placeholder="https://你的语音接口域名/v1" value="${escapeHtml(voiceConfig.base||'')}"></label><label>语音 API Key<input name="voiceKey" type="password" autocomplete="off" placeholder="填写语音服务的密钥" value="${escapeHtml(voiceKey)}"></label><label class="check"><input name="rememberVoice" type="checkbox" ${voiceConfig.remember?'checked':''}>在此浏览器记住语音密钥</label></div><label>录音转文字模型<input name="stt" value="${escapeHtml(voiceSettings.stt)}" placeholder="服务商的 transcription 模型名称"></label><label>文字转语音模型 · 可选<input name="tts" value="${escapeHtml(voiceSettings.tts)}" placeholder="服务商的 speech 模型名称"></label><label>声音名称<input name="voice" value="${escapeHtml(voiceSettings.voice)}" placeholder="服务商支持的 voice 名称"></label><label class="check"><input name="autoPlay" type="checkbox" ${voiceSettings.autoPlay?'checked':''}>文字聊天回复后自动播放语音</label><button class="primary full">保存语音 API 配置</button></form><p class="api-note">兼容 /audio/transcriptions 和 /audio/speech。未填语音合成模型时使用浏览器朗读。服务商需允许 CORS。语音聊天采用轮流说话模式。选择共用配置时，请先保存上方聊天 API。</p><button class="secondary full" id="testVoice">试听一句问候</button>`;
  if(embedded)$('#voiceAPISection').innerHTML=html;else{go('api');return}
  const f=$('#voiceForm'),change=()=>{$('#voiceCredentials').hidden=f.sameAsChat.checked;f.voiceBase.required=!f.sameAsChat.checked;f.voiceKey.required=!f.sameAsChat.checked};f.sameAsChat.onchange=change;change();
  f.onsubmit=e=>{e.preventDefault();const nextSettings={stt:f.stt.value.trim(),tts:f.tts.value.trim(),voice:f.voice.value.trim()||'alloy',autoPlay:f.autoPlay.checked},nextConfig={base:f.voiceBase.value.trim().replace(/\/+$/,''),key:f.rememberVoice.checked?f.voiceKey.value.trim():'',remember:f.rememberVoice.checked,sameAsChat:f.sameAsChat.checked};try{if(!nextConfig.sameAsChat)PalaisCore.apiURL(nextConfig.base,'audio/speech');localSave('voiceConnection',{config:nextConfig,settings:nextSettings});voiceConfig=nextConfig;voiceSettings=nextSettings;voiceKey=f.voiceKey.value.trim();toast('语音 API 配置已保存')}catch(err){toast(err.message)}};
  $('#testVoice').onclick=()=>playSpeech('你好，欢迎回到你的玫瑰小宫殿。').catch(e=>toast(friendly(e)));
}
const savedVoice=localRead('voiceConnection',null);if(savedVoice){voiceConfig=savedVoice.config;voiceSettings=savedVoice.settings;voiceKey=voiceConfig.remember?voiceConfig.key||'':'';}

async function playSpeech(text){if(phoneLocked)return;speechController?.abort();speechController=new AbortController();const speechSignal=AbortSignal.any([speechController.signal,AbortSignal.timeout(60000)]);if(currentAudio){currentAudio.pause();URL.revokeObjectURL(currentAudio.src);currentAudio=null}if('speechSynthesis'in window)speechSynthesis.cancel();
  if(!voiceSettings.tts){if(!('speechSynthesis'in window))throw Error('此浏览器不支持朗读，请配置语音合成模型');const utterance=new SpeechSynthesisUtterance(text);utterance.lang='zh-CN';utterance.rate=.95;speechSynthesis.speak(utterance);return}
  if(!voiceReady())throw Error('请先保存语音 API 地址和密钥');const c=effectiveVoiceConfig(),res=await fetch(PalaisCore.apiURL(c.base,'audio/speech'),{method:'POST',headers:{Authorization:'Bearer '+c.key,'Content-Type':'application/json'},body:JSON.stringify({model:voiceSettings.tts,input:text.slice(0,4000),voice:voiceSettings.voice,response_format:'mp3'}),signal:speechSignal});if(!res.ok){let data;try{data=await res.json()}catch{}throw Error('语音合成失败（HTTP '+res.status+'）'+(data?.error?.message?'：'+data.error.message:''))}const blob=await res.blob();if(!blob.type.startsWith('audio/')&&blob.type!=='application/octet-stream')throw Error('接口没有返回音频');if(phoneLocked)return;const url=URL.createObjectURL(blob),audio=new Audio(url);currentAudio=audio;audio.onended=()=>{URL.revokeObjectURL(url);if(currentAudio===audio)currentAudio=null};try{await audio.play()}catch{URL.revokeObjectURL(url);throw Error('自动播放被浏览器阻止，请点回复旁的朗读按钮')}
}
function openVoiceChat(r){if(busy){toast('等本轮聊天结束后再开始语音');return}if(!apiReady()){requireAPI();return}if(!voiceReady()){toast('请先连接语音 API');go('api');return}if(!voiceSettings.stt){toast('请先填写录音转文字模型');go('voice');return}voiceMode=true;voiceRole=r;const d=panel(`<div class="eyebrow">LET YOUR VOICE REACH ME</div><h2>与${escapeHtml(r.name)}语音聊天</h2><div class="voice-orb">♫</div><p class="voice-status" id="voiceStatus">点开始说话，单次最多 60 秒。</p><div class="actions"><button class="primary" id="startCallRecording">开始说话</button><button class="secondary" id="stopCallRecording" disabled>说完并发送</button></div><p class="api-note">录音会发送至你的 API。转写内容会保存到聊天记录；回复会尝试播放语音。</p><button class="secondary full" id="closeVoiceChat">结束语音聊天</button>`);$('#startCallRecording').onclick=()=>startRecording(r,true);$('#stopCallRecording').onclick=()=>finishRecording();$('#closeVoiceChat').onclick=()=>{stopVoice();d.close()};d.addEventListener('close',stopVoice,{once:true})}
async function startRecording(r,inCall=false){if(phoneLocked||busy||voiceProcessing){toast('请等本轮回复结束');return}if(recorder?.state==='recording'){finishRecording();return}if(!voiceReady()){toast('请先连接语音 API');go('api');return}if(!voiceSettings.stt){toast('先在 API 设置中填写录音转文字模型');go('voice');return}if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('此浏览器不支持录音，请使用支持录音的浏览器');return}
  try{recordStream=await navigator.mediaDevices.getUserMedia({audio:true});if(phoneLocked){recordStream.getTracks().forEach(t=>t.stop());return}const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(m=>MediaRecorder.isTypeSupported(m));recorder=new MediaRecorder(recordStream,mime?{mimeType:mime}:{});recordChunks=[];const started=Date.now();recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data)};
    recorder.onstop=async()=>{clearTimeout(recordTimeout);recordStream?.getTracks().forEach(t=>t.stop());const blob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});recorder=null;if(phoneLocked||inCall&&!voiceMode)return;voiceProcessing=true;voiceStatus('正在把录音转成文字…');setCallButtons(true);const mic=$('#recordMessage');if(mic)mic.textContent='…';try{if(Date.now()-started<500||!blob.size)throw Error('录音太短，请再说一次');const form=new FormData();form.append('file',blob,blob.type.includes('mp4')?'recording.m4a':'recording.webm');form.append('model',voiceSettings.stt);const c=effectiveVoiceConfig(),res=await fetch(PalaisCore.apiURL(c.base,'audio/transcriptions'),{method:'POST',headers:{Authorization:'Bearer '+c.key},body:form,signal:AbortSignal.timeout(60000)});let data;try{data=await res.json()}catch{throw Error('语音转写接口未返回有效 JSON')}if(!res.ok)throw Error('语音转写失败（HTTP '+res.status+'）'+(data.error?.message?'：'+data.error.message:''));if(typeof data.text!=='string'||!data.text.trim())throw Error('没有识别到文字，请再说一次');if(phoneLocked||inCall&&!voiceMode)return;
      if(inCall){voiceStatus('你说：'+data.text+'\n正在等待回复…');await sendMessage(r,data.text.trim());voiceStatus('这一轮结束了，可以继续说话。')}else{if(isChatView()&&current===r.id&&$('#composer textarea')){$('#composer textarea').value=data.text.trim();toast('录音已转为文字，确认后发送')}else toast('已离开原聊天，请回到对话后重新录音')}
    }catch(err){toast(friendly(err));voiceStatus(friendly(err))}finally{voiceProcessing=false;setCallButtons(false);if($('#recordMessage'))$('#recordMessage').textContent='♫'}};
    recorder.start();recordTimeout=setTimeout(finishRecording,60000);voiceStatus('正在听你说话…');if(inCall){$('#startCallRecording').disabled=true;$('#stopCallRecording').disabled=false}else if($('#recordMessage'))$('#recordMessage').textContent='■';
  }catch(err){toast(err.name==='NotAllowedError'?'麦克风权限未开启，请在浏览器中允许录音':friendly(err));recordStream?.getTracks().forEach(t=>t.stop())}
}
function voiceStatus(text){if($('#voiceStatus'))$('#voiceStatus').textContent=text}
function setCallButtons(processing){if($('#startCallRecording'))$('#startCallRecording').disabled=processing;if($('#stopCallRecording'))$('#stopCallRecording').disabled=true}
function finishRecording(){if(recorder?.state==='recording')recorder.stop()}
